    24	  if (definition.type !== "function" || !definition.function || definition.function.name !== toolName) {
    25	    throw new Error(`registered schema for ${toolName} is not a function tool`);
    26	  }
    27	  const parameters = definition.function.parameters as unknown;
    28	  if (!parameters || typeof parameters !== "object" || Array.isArray(parameters)) {
    29	    throw new Error(`registered schema for ${toolName} must define an object parameter schema`);
    30	  }
    31	
