    33	  rejectUnknownKeys(schema, new Set(["type", "properties", "required"]), `${toolName} parameter schema`);
    34	  if (schema.type !== "object") throw new Error(`registered schema for ${toolName} must have type object`);
    35	  if (!schema.properties || typeof schema.properties !== "object" || Array.isArray(schema.properties)) {
    36	    throw new Error(`registered schema for ${toolName} must define flat properties`);
    37	  }
    38	
    39	  const propertyMap = schema.properties as Record<string, unknown>;
    40	  const propertyNames = Object.keys(propertyMap);
    41	  if (propertyNames.length > MAX_PROPERTIES) throw new Error(`${toolName} schema exceeds the ${MAX_PROPERTIES}-property GBNF bound`);
    42	  const required = schema.required === undefined ? [] : schema.required;
    43	  if (!Array.isArray(required) || required.some((name) => typeof name !== "string")) {
    44	    throw new Error(`registered schema for ${toolName} has an invalid required list`);
    45	  }
    46	  if (new Set(required).size !== required.length) throw new Error(`registered schema for ${toolName} repeats a required property`);
    47	  for (const name of required) {
    48	    if (!Object.hasOwn(propertyMap, name)) throw new Error(`registered schema for ${toolName} requires undeclared property ${name}`);
    49	  }
