  1024	  private async executeWithFailover<T>(
  1025	    operationName: string,
  1026	    operation: (endpoint: string) => Promise<T>
  1027	  ): Promise<T> {
  1028	    const total = this.endpoints.length;
  1029	    let lastError: Error | null = null;
  1030	
  1031	    for (let attempt = 0; attempt < total; attempt++) {
  1032	      const idx = (this.activeEndpointIndex + attempt) % total;
  1033	      const currentEp = this.endpoints[idx];
  1034	      // An endpoint not authorized for cloud disclosure is never tried; a fallback never widens disclosure.
  1035	      const denial = this.disclosureDenial(currentEp);
  1036	      if (denial) {
  1037	        lastError = lastError ?? denial;
  1038	        continue;
  1039	      }
  1040	
  1041	      try {
  1042	        const result = await operation(currentEp);
  1043	        if (idx !== this.activeEndpointIndex) {
  1044	          this.emitDiagnostic("warn",
  1045	            pc.yellow(`\n⚡ Failover: Active inference endpoint switched to ${currentEp}`)
  1046	          );
  1047	          this.activeEndpointIndex = idx;
  1048	        }
  1049	        return result;
  1050	      } catch (err: any) {
  1051	        lastError = err;
  1052	        if (err instanceof InferenceError && !err.failoverEligible) throw err;
  1053	        if (total > 1 && attempt < total - 1) {
  1054	          const nextIdx = (idx + 1) % total;
  1055	          this.emitDiagnostic("warn",
  1056	            pc.dim(
  1057	              `⚠️ [Failover] ${operationName} failed on ${currentEp} (${err.message}). Trying backup endpoint ${this.endpoints[nextIdx]}...`
  1058	            )
  1059	          );
  1060	        }
  1061	      }
  1062	    }
  1063	
  1064	    throw (
  1065	      lastError ||
  1066	      new Error(
  1067	        `All inference endpoints failed for ${operationName} (attempted: ${this.endpoints.join(", ")})`
  1068	      )
  1069	    );
  1070	  }
