  11	/** Compile the exact parameter schema registered for one allowlisted tool. Unknown JSON Schema forms fail closed. */
  12	export function generateToolArgumentsGbnf(
  13	  toolName: GbnfToolName,
  14	  registeredTools: readonly ToolDefinition[] = HARNESS_TOOLS,
  15	): string {
  16	  if (!ALLOWED_NAMES.has(toolName)) throw new Error(`GBNF is not enabled for tool ${String(toolName)}`);
  17	  if (!Array.isArray(registeredTools)) throw new Error("registered tool definitions must be an array");
  18	
  19	  const matches = registeredTools.filter((tool) => (tool as ToolDefinition | undefined)?.function?.name === toolName);
  20	  if (matches.length !== 1) {
  21	    throw new Error(`expected exactly one registered schema for ${toolName}; found ${matches.length}`);
  22	  }
  23	  const definition = matches[0] as ToolDefinition;
  24	  if (definition.type !== "function" || !definition.function || definition.function.name !== toolName) {
  25	    throw new Error(`registered schema for ${toolName} is not a function tool`);
  26	  }
  27	  const parameters = definition.function.parameters as unknown;
  28	  if (!parameters || typeof parameters !== "object" || Array.isArray(parameters)) {
  29	    throw new Error(`registered schema for ${toolName} must define an object parameter schema`);
  30	  }
  31	
  32	  const schema = parameters as Record<string, unknown>;
  33	  rejectUnknownKeys(schema, new Set(["type", "properties", "required"]), `${toolName} parameter schema`);
  34	  if (schema.type !== "object") throw new Error(`registered schema for ${toolName} must have type object`);
  35	  if (!schema.properties || typeof schema.properties !== "object" || Array.isArray(schema.properties)) {
  36	    throw new Error(`registered schema for ${toolName} must define flat properties`);
  37	  }
  38	
  39	  const propertyMap = schema.properties as Record<string, unknown>;
  40	  const propertyNames = Object.keys(propertyMap);
  41	  if (propertyNames.length > MAX_PROPERTIES) throw new Error(`${toolName} schema exceeds the ${MAX_PROPERTIES}-property GBNF bound`);
  42	  const required = schema.required === undefined ? [] : schema.required;
  43	  if (!Array.isArray(required) || required.some((name) => typeof name !== "string")) {
  44	    throw new Error(`registered schema for ${toolName} has an invalid required list`);
  45	  }
  46	  if (new Set(required).size !== required.length) throw new Error(`registered schema for ${toolName} repeats a required property`);
  47	  for (const name of required) {
  48	    if (!Object.hasOwn(propertyMap, name)) throw new Error(`registered schema for ${toolName} requires undeclared property ${name}`);
  49	  }
  50	
  51	  const properties = propertyNames.map((name, index) => {
  52	    const raw = propertyMap[name];
  53	    if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
  54	      throw new Error(`registered property ${toolName}.${name} must be a flat schema object`);
  55	    }
  56	    const property = raw as Record<string, unknown>;
  57	    const valueRule = property.type === "string" ? "json-string"
  58	      : property.type === "number" ? "json-number"
  59	        : property.type === "boolean" ? "json-boolean"
  60	          : undefined;
  61	    if (!valueRule) throw new Error(`unsupported JSON Schema type for ${toolName}.${name}`);
  62	    rejectUnknownKeys(property, new Set(["type", "description"]), `${toolName}.${name} schema`);
  63	    if (typeof property.description !== "undefined" && typeof property.description !== "string") {
  64	      throw new Error(`registered property ${toolName}.${name} has an invalid description`);
  65	    }
  66	    return { name, index, valueRule };
  67	  });
  68	
  69	  const propertyIndex = new Map(properties.map(({ name, index }) => [name, index]));
  70	  const requiredMask = required.reduce((mask: number, name: string) => mask | (1 << propertyIndex.get(name)!), 0);
  71	  const stateCount = 1 << properties.length;
  72	  const rules = [
  73	    "root ::= ws \"{\" ws object-fields ws \"}\" ws",
  74	    "json-string ::= \"\\\"\" json-char* \"\\\"\"",
  75	    String.raw`json-char ::= [^"\\\x00-\x1f] | "\\" (["\\/bfnrt] | "u" [0-9a-fA-F]{4})`,
  76	    String.raw`json-number ::= "-"? ("0" | [1-9] [0-9]*) ("." [0-9]+)? ([eE] [-+]? [0-9]+)?`,
  77	    "json-boolean ::= \"true\" | \"false\"",
  78	    "ws ::= [ \\t\\n\\r]*",
  79	    ...properties.map(({ name, index, valueRule }) => `member_${index} ::= ${JSON.stringify(name)} ws ":" ws ${valueRule}`),
  80	  ];
  81	
  82	  const firstChoices = properties.map(({ index }) => `member_${index} fields_tail_${1 << index}`);
  83	  rules.push(`object-fields ::= ${requiredMask === 0 ? '"" | ' : ""}${firstChoices.length ? firstChoices.join(" | ") : '""'}`);
  84	  for (let mask = 0; mask < stateCount; mask++) {
  85	    const choices: string[] = [];
  86	    if ((mask & requiredMask) === requiredMask) choices.push('""');
  87	    for (const { index } of properties) {
  88	      const bit = 1 << index;
  89	      if ((mask & bit) === 0) choices.push(`"," ws member_${index} fields_tail_${mask | bit}`);
  90	    }
  91	    // Only reachable states need a rule, but emitting all bounded masks keeps output deterministic and simple.
  92	    rules.push(`fields_tail_${mask} ::= ${choices.join(" | ") || '""'}`);
  93	  }
  94	  return rules.join("\n");
